syntax = "proto3";

message SearchRequest {
  string query = 1;
  int32  page  = 2;
  repeated string tags = 3;            // 列表

  enum Sort { SORT_UNSPECIFIED = 0; DATE = 1; SCORE = 2; }
  Sort sort = 4;

  map<string, string> params = 5;      // 字典

  oneof condition {
    bool include_deleted = 6;          // 三选一
    string owner = 7;
    int64  before_ts  = 8;
  }

  optional int32 limit = 9;            // 可显式区分空值
}

